function computeIdf(docBags: Array<Set<string>>): Map<string, number> {
  const df = new Map<string, number>();
  for (const bag of docBags)
    for (const t of bag) df.set(t, (df.get(t) ?? 0) + 1);
  return idfFromDf(df, docBags.length);
}
